type PaymentMethod =
  | { kind: "card"; scheme: string }
  | { kind: "sepa" }
  | { kind: "pix"; key: string };

function fee(m: PaymentMethod, amount: number) {
  switch (m.kind) {
    case "card": return amount * 0.029;
    case "sepa": return 0.35;
  }
}

